import { expect, test } from "bun:test";
import { canonicalSealedDeployAggregate } from "../../src/publication/napplet-cli-adapter";

test("aggregate matches the actual pinned named CLI dry-run receipt", () => {
  // Captured by the real worker CLI gate, not generated by this helper.
  expect(canonicalSealedDeployAggregate([{ path: "/index.html", mimeType: "text/html", size: 1,
    sha256: "4c7a0075b44b2f6b677f3627119a62a423fb8d9539b8f546ff4eea2dc1a73c11" }]))
    .toBe("f1619584d8dd33d1c7c44a2dab22e3786e8927bc12d125e0c4437277902af5e5");
});

test("aggregate sorts complete CLI lines while MIME and size stay separate", () => {
  const files = [{ path: "/a.html", mimeType: "text/html", size: 1, sha256: "b".repeat(64) }, { path: "/z.js", mimeType: "text/javascript", size: 2, sha256: "a".repeat(64) }];
  // Independent fixed vector: sha256(a*64 + ' /z.js\n' + b*64 + ' /a.html\n').
  expect(canonicalSealedDeployAggregate(files)).toBe("b927af4d148482c79cf09c0bee3924f43a02c1b8c5a43c8d9c0ef81e5300b0a2");
  expect(canonicalSealedDeployAggregate([...files].reverse())).toBe("b927af4d148482c79cf09c0bee3924f43a02c1b8c5a43c8d9c0ef81e5300b0a2");
  expect(canonicalSealedDeployAggregate(files.map(file => ({ ...file, mimeType: "application/octet-stream", size: 99 })))).toBe("b927af4d148482c79cf09c0bee3924f43a02c1b8c5a43c8d9c0ef81e5300b0a2");
  expect(() => canonicalSealedDeployAggregate([files[0]!, files[0]!])).toThrow("SEALED_NAMED_DEPLOY_INVALID");
});
